div.script:
/* ---------- icons (inline SVG, no emojis) ---------- */
const I = {
  drop: '<path d="M12 22a7 7 0 0 0 7-7c0-2-1-3.9-3-5.5s-3.5-4-4-6.5c-.5 2.5-2 4.9-4 6.5C6 11.1 5 13 5 15a7 7 0 0 0 7 7z"/>',
  gamepad: '<path d="M6 11h4M8 9v4M15 12h.01M18 10h.01"/><path d="M17.32 5H6.68a4 4 0 0 0-3.98 3.59C2.6 9.42 2 14.46 2 16a3 3 0 0 0 3 3c1 0 1.5-.5 2-1l1.41-1.41A2 2 0 0 1 9.83 16h4.34a2 2 0 0 1 1.41.59L17 18c.5.5 1 1 2 1a3 3 0 0 0 3-3c0-1.55-.6-6.58-.69-7.26A4 4 0 0 0 17.32 5z"/>',
  sparkles: '<path d="M9.94 15.5A2 2 0 0 0 8.5 14.06l-6.13-1.58a.5.5 0 0 1 0-.96L8.5 9.94A2 2 0 0 0 9.94 8.5l1.58-6.13a.5.5 0 0 1 .96 0L14.06 8.5a2 2 0 0 0 1.44 1.44l6.13 1.58a.5.5 0 0 1 0 .96l-6.13 1.58a2 2 0 0 0-1.44 1.44l-1.58 6.13a.5.5 0 0 1-.96 0z"/>',
  film: '<rect width="18" height="18" x="3" y="3" rx="2"/><path d="M7 3v18M3 7.5h4M3 12h18M3 16.5h4M17 3v18M17 7.5h4M17 16.5h4"/>',
  music: '<path d="M9 18V5l12-2v13"/><circle cx="6" cy="18" r="3"/><circle cx="18" cy="16" r="3"/>',
  chat: '<path d="M7.9 20A9 9 0 1 0 4 16.1L2 22z"/>',
  weather: '<path d="M12 2v2M4.93 4.93l1.41 1.41M20 12h2M19.07 4.93l-1.41 1.41M15.95 12.65a4 4 0 0 0-5.93-4.13M13 22H7a5 5 0 1 1 4.9-6H13a3 3 0 0 1 0 6z"/>',
  grid: '<rect width="7" height="7" x="3" y="3" rx="1"/><rect width="7" height="7" x="14" y="3" rx="1"/><rect width="7" height="7" x="14" y="14" rx="1"/><rect width="7" height="7" x="3" y="14" rx="1"/>',
  plus: '<path d="M5 12h14M12 5v14"/>',
  arrowLeft: '<path d="m12 19-7-7 7-7M19 12H5"/>',
  arrowRight: '<path d="M5 12h14M12 5l7 7-7 7"/>',
  refresh: '<path d="M3 12a9 9 0 0 1 9-9 9.75 9.75 0 0 1 6.74 2.74L21 8M21 3v5h-5M21 12a9 9 0 0 1-9 9 9.75 9.75 0 0 1-6.74-2.74L3 16M8 16H3v5"/>',
  x: '<path d="M18 6 6 18M6 6l12 12"/>',
  bookmark: '<path d="m19 21-7-4-7 4V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2v16z"/>',
  shuffle: '<path d="M2 18h1.4c1.3 0 2.5-.6 3.3-1.7l6.1-8.6c.7-1.1 2-1.7 3.3-1.7H22M18 2l4 4-4 4M2 6h1.9c1.5 0 2.9.9 3.6 2.2M22 18h-5.9c-1.3 0-2.6-.7-3.3-1.8l-.5-.8M18 14l4 4-4 4"/>',
  globe: '<circle cx="12" cy="12" r="10"/><path d="M12 2a14.5 14.5 0 0 0 0 20 14.5 14.5 0 0 0 0-20M2 12h20"/>',
  alert: '<path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3zM12 9v4M12 17h.01"/>'
};
function ico(n, s = 20) {
  const d = mk("span");
  d.className = "svg";
  d.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" width="' + s + '" height="' + s + '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' + I[n] + "</svg>";
  return d;
}
// site icon: fetched favicon, falls back to a globe icon
function fav(u, size) {
  const img = new Image();
  img.alt = "";
  img.loading = "lazy";
  img.referrerPolicy = "no-referrer";
  img.src = "https://www.google.com/s2/favicons?domain=" + new URL(u).hostname + "&sz=128";
  img.onerror = () => img.replaceWith(ico("globe", size));
  return img;
}

/* ---------- data: "Name|domain/path" ---------- */
const P = (s) => s.split(",").map((x) => { const [n, u] = x.trim().split("|"); return { n, u: "https://" + u }; });

const pages = {
  g: { title: "Games", icon: "gamepad", sites: P(`Roblox|www.roblox.com, Poki|poki.com, CrazyGames|www.crazygames.com, Miniclip|www.miniclip.com, Y8|www.y8.com, Itch.io|itch.io, Steam|store.steampowered.com, Epic Games|store.epicgames.com, Chess.com|www.chess.com, Lichess|lichess.org, Slither.io|slither.io, Krunker|krunker.io, Agar.io|agar.io, Shell Shockers|shellshock.io, 2048|play2048.co, Cool Math Games|www.coolmathgames.com, Armor Games|armorgames.com, Newgrounds|www.newgrounds.com, GeoGuessr|www.geoguessr.com, Wordle|www.nytimes.com/games/wordle, Little Alchemy 2|littlealchemy2.com, Skribbl.io|skribbl.io, Minecraft|www.minecraft.net, Friv|www.friv.com`) },
  ai: { title: "AI", icon: "sparkles", sites: P(`ChatGPT|chatgpt.com, Claude|claude.ai, Gemini|gemini.google.com, Perplexity|www.perplexity.ai, Copilot|copilot.microsoft.com, Grok|grok.com, DeepSeek|chat.deepseek.com, Le Chat|chat.mistral.ai, Character.AI|character.ai, Midjourney|www.midjourney.com, Hugging Face|huggingface.co, Poe|poe.com`) },
  m: { title: "Movies", icon: "film", sites: P(`YouTube|www.youtube.com, Netflix|www.netflix.com, Tubi|tubitv.com, Pluto TV|pluto.tv, Disney+|www.disneyplus.com, Max|www.max.com, Prime Video|www.primevideo.com, Hulu|www.hulu.com, Crunchyroll|www.crunchyroll.com, IMDb|www.imdb.com, Twitch|www.twitch.tv, Vimeo|vimeo.com`) },
  music: { title: "Music", icon: "music", sites: P(`YouTube Music|music.youtube.com, Spotify|open.spotify.com, SoundCloud|soundcloud.com, Pandora|www.pandora.com, Apple Music|music.apple.com, Deezer|www.deezer.com, Tidal|tidal.com, Bandcamp|bandcamp.com, Last.fm|www.last.fm, Genius|genius.com, Audiomack|audiomack.com`) },
  c: { title: "Chat", icon: "chat", sites: P(`Discord|discord.com/app, Messenger|www.messenger.com, WhatsApp|web.whatsapp.com, Telegram|web.telegram.org, Slack|app.slack.com, Reddit|www.reddit.com, Google Chat|chat.google.com, Teams|teams.microsoft.com`) },
  w: { title: "Weather", icon: "weather", sites: P(`Weather.com|weather.com, AccuWeather|www.accuweather.com, Windy|www.windy.com, Weather.gov|www.weather.gov, Ventusky|www.ventusky.com, Wunderground|www.wunderground.com`) },
  apps: { title: "All Apps", icon: "grid", all: true }
};


const alias = { games: "g", game: "g", movies: "m", movie: "m", chat: "c", weather: "w", home: "home" };

/* ---------- state ---------- */
let bookmarks = [];
try { bookmarks = JSON.parse(localStorage.getItem("milky-bm") || "[]"); } catch (e) {}
const saveBm = () => { try { localStorage.setItem("milky-bm", JSON.stringify(bookmarks)); } catch (e) {} };

let uid = 0;
let tabs = [{ id: ++uid, route: "home" }];
let active = tabs[0].id;

const XHTML = "http://www.w3.org/1999/xhtml";
const root = document.currentScript.parentNode;
const _cens = document.createElementNS.bind(document);
const mk = (t) => _cens(XHTML, t);
// Scripts loaded later (Scramjet) expect an HTML-style document.
document.createElement = (t) => mk(t);
for (const k of ["body", "head"]) Object.defineProperty(document, k, { get: () => root, configurable: true });
const $ = (s) => root.querySelector(s.charAt(0) === "#" ? '[id="' + s.slice(1) + '"]' : s);
function el(tag, cls, text) { const e = mk(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; }

/* ---------- url helpers ---------- */
// Anything typed that isn't a URL or a domain gets sent to this search engine.
const SEARCH = "https://search.brave.com/search?q=";

function toUrl(v) {
  v = (v || "").trim();
  if (/^https?:\/\//i.test(v)) return v;                          // full URL
  if (/^(localhost|[\w-]+(\.[\w-]+)+)(:\d+)?([\/?#]\S*)?$/i.test(v))
    return "https://" + v;                                         // looks like a domain
  return SEARCH + encodeURIComponent(v);                           // otherwise search
}

function hostOf(u) {
  try { return new URL(u).hostname.replace(/^www\./, ""); }
  catch (e) { return u; }
}

// Used by site cards, bookmarks, game tiles and the Random button.
// Opens in the current tab if it's a fresh home tab, otherwise a new tab.
function openTarget(u) { openSite(u, true); }

/* ---------- proxy engine: Scramjet runs in this page + a service worker; the Pi only relays traffic ---------- */
// Folder this file is served from, e.g. /gh/YOURNAME/YOURREPO@HASH/  (also the service worker scope)
const BASE = new URL(".", location.href).pathname;
const PREFIX = BASE + "p/";                                   // virtual addresses the service worker answers
const WISP_URL = "wss://minecraft.perch-dace.ts.net/cron/";   // <-- your Pi's Wisp endpoint (see instructions)
const TRANSPORT = "epoxy";                                    // "epoxy" or "libcurl"
const TRANSPORT_FILES = { epoxy: "epoxy/index.mjs", libcurl: "libcurl/index.mjs" };

let toastEl = null, toastTimer = 0;
function toast(msg, err, sticky) {
  if (!toastEl) { toastEl = el("div", "mk-toast"); root.append(toastEl); }
  toastEl.textContent = msg;
  toastEl.className = "mk-toast" + (err ? " err" : "");
  toastEl.style.display = "block";
  clearTimeout(toastTimer);
  if (!sticky) toastTimer = setTimeout(() => { toastEl.style.display = "none"; }, 5000);
}
function hideToast() { if (toastEl) toastEl.style.display = "none"; }

function loadScript(src) {
  return new Promise((resolve, reject) => {
    const s = mk("script");
    s.src = src;
    s.onload = () => resolve();
    s.onerror = () => reject(new Error("could not load " + src));
    root.append(s);
  });
}

async function bootProxy() {
  if (!navigator.serviceWorker) throw new Error("service workers are not available here (needs https)");

  // Remove workers left over from other commits of this repo (each commit link is its own scope).
  if (/@[^/]*\/$/.test(BASE)) {
    const stem = BASE.replace(/@[^/]*\/$/, "@");
    for (const r of await navigator.serviceWorker.getRegistrations()) {
      const p = new URL(r.scope).pathname;
      if (p.startsWith(stem) && p !== BASE) await r.unregister();
    }
  }

  const reg = await navigator.serviceWorker.register(BASE + "sw.js", { scope: BASE });
  await navigator.serviceWorker.ready;
  if (!navigator.serviceWorker.controller) {
    await new Promise((resolve) => {
      navigator.serviceWorker.addEventListener("controllerchange", () => resolve(), { once: true });
      setTimeout(resolve, 5000);
    });
  }

  await loadScript(BASE + "scram/working.js");
  await loadScript(BASE + "scram/working-ctrl.api.js");
  await loadScript(BASE + "scram/scramjet-utils.js");

  const { Controller } = $scramjetController;
  const { defaultConfig } = $scramjet;

  const mod = await import(BASE + TRANSPORT_FILES[TRANSPORT]);
  const transport = new mod.default({ wisp: WISP_URL });
  if (typeof transport.init === "function") await transport.init();

  const serviceworker = navigator.serviceWorker.controller || reg.active;
  if (!serviceworker) throw new Error("no service worker is controlling the page");

  const controller = new Controller({
    serviceworker,
    transport,
    config: {
      prefix: PREFIX,
      scramjetPath: BASE + "scram/working.js",
      wasmPath: BASE + "scram/working.wasm",
      injectPath: BASE + "scram/working-ctrl.inject.js",
    },
    scramjetConfig: {
      ...defaultConfig,
      flags: { ...defaultConfig.flags, allowFailedIntercepts: true, allowInvalidJs: true },
    },
  });

  await Promise.race([
    controller.wait(),
    new Promise((_, reject) => setTimeout(() => reject(new Error("proxy handshake timed out")), 15000)),
  ]);
  return controller;
}

let sjPromise = null;
function getController() {
  if (!sjPromise) {
    toast("Starting proxy…", false, true);
    sjPromise = bootProxy().then((c) => { hideToast(); return c; }).catch((e) => {
      sjPromise = null;
      console.error("[milky] proxy failed to start:", e);
      toast("Proxy failed to start: " + ((e && e.message) || e), true, true);
      throw e;
    });
  }
  return sjPromise;
}

// Keep the address bar and tab title in sync with where the proxied page actually is.
function onFrameUrl(t, u) {
  const s = String((u && u.href) || u || "");
  if (!/^https?:/i.test(s)) return;
  t.url = s;
  t.title = hostOf(s);
  renderTabs();
  if (t.id === active) {
    const a = $("#addr");
    if (a && !a.matches(":focus")) a.value = s;
  }
}
function framePlugins(t) {
  if (typeof $scramjetUtils === "undefined") return [];
  const p = [];
  try { p.push(new $scramjetUtils.HttpCachePlugin()); } catch (e) {}
  try { p.push(new $scramjetUtils.UrlWatcherPlugin((u) => onFrameUrl(t, u))); } catch (e) {}
  return p;
}

function attachSj(t, f) {
  getController().then((c) => {
    if (t.frame !== f || t.direct) return;        // tab closed, sent home, or switched to a direct page meanwhile
    t.sj = c.createFrame(f, { plugins: framePlugins(t) });
    t.sj.go(t.url);
  }).catch(() => {});
}

function createFrame(t) {
  const f = mk("iframe");
  f.allow = "fullscreen; autoplay; clipboard-write; encrypted-media";
  t.frame = f;
  $("#frames").append(f);
  if (t.direct) f.src = t.url;                    // page that allows framing: loads itself, no proxy needed
  else attachSj(t, f);
}

function openSite(v, reuse, direct) {
  v = (v || "").trim();
  if (!v) return;

  const url = toUrl(v);
  let t = tabs.find((x) => x.id === active);

  if (!(reuse && t.route === "home")) {
    t = { id: ++uid };
    tabs.push(t);
    active = t.id;
  }

  t.route = "site";
  t.url = url;
  t.title = hostOf(url);
  t.direct = !!direct;

  createFrame(t);
  render();
}

function navSite(t, v) {
  const url = toUrl(v);
  t.url = url;
  t.title = hostOf(url);
  if (t.direct) { t.direct = false; attachSj(t, t.frame); }   // typing a new address moves this tab onto the proxy
  else if (t.sj) t.sj.go(url);                                 // otherwise createFrame() uses t.url once the proxy is ready
  render();
}

function navAct(kind) {
  const t = tabs.find((x) => x.id === active);
  if (!t || t.route !== "site" || !t.frame) return;
  if (t.direct) { if (kind === "reload") t.frame.src = t.url; return; }   // cross-origin page: browser blocks back/forward
  if (t.sj && typeof t.sj[kind] === "function") { t.sj[kind](); return; }
  try {
    const w = t.frame.contentWindow;
    if (kind === "back") w.history.back();
    else if (kind === "forward") w.history.forward();
    else if (kind === "reload") w.location.reload();
  } catch (e) {}
}

[["back", "arrowLeft"], ["forward", "arrowRight"], ["reload", "refresh"]].forEach(([k, ic]) => {
  const b = $("#nb-" + k);
  b.append(ico(ic, 16));
  b.onclick = () => navAct(k);
});

/* ---------- navigation ---------- */
function resolve(v) {
  const m = v.trim().match(/^milky:\/\/(.*)$/i);
  if (!m) return null;
  const r = m[1].replace(/\/+$/, "").toLowerCase() || "home";
  return alias[r] || r;
}
function go(route, newTab) {
  if (newTab) {
    const ex = route !== "home" && tabs.find((t) => t.route === route);
    if (ex) active = ex.id;
    else { const t = { id: ++uid, route }; tabs.push(t); active = t.id; }
  } else {
    const t = tabs.find((x) => x.id === active);
    if (t.frame) { t.frame.remove(); t.frame = null; t.sj = null; }
    t.route = route;
  }
  render();
}
function submit(v) {
  const r = resolve(v);
  if (r) { go(r, false); return; }
  const t = tabs.find((x) => x.id === active);
  if (t.route === "site") navSite(t, v);
  else openSite(v, true);
}
function closeTab(id) {
  const i = tabs.findIndex((t) => t.id === id);
  if (tabs[i].frame) tabs[i].frame.remove();
  tabs.splice(i, 1);
  if (!tabs.length) tabs.push({ id: ++uid, route: "home" });
  if (active === id) active = tabs[Math.max(0, i - 1)].id;
  render();
}

/* ---------- render ---------- */
const tabInfo = (t) => (t.route === "site" ? { title: t.title, icon: "globe" } : t.route === "home" ? { title: "Milky", icon: "drop" } : pages[t.route] || { title: "Not found", icon: "alert" });

function renderTabs() {
  const bar = $("#tabbar");
  bar.innerHTML = "";
  tabs.forEach((t) => {
    const info = tabInfo(t);
    const b = el("div", "tab" + (t.id === active ? " active" : ""));
    b.append(ico(info.icon, 15), el("span", "t", info.title));
    const x = el("button", "x");
    x.title = "Close tab";
    x.append(ico("x", 13));
    x.onclick = (e) => { e.stopPropagation(); closeTab(t.id); };
    b.append(x);
    b.onclick = () => { active = t.id; render(); };
    bar.append(b);
  });
  const n = el("button", "newtab");
  n.title = "New tab";
  n.append(ico("plus", 18));
  n.onclick = () => go("home", true);
  bar.append(n);
}

function tile(icon, label, fn, cls) {
  const b = el("button", "tile " + (cls || ""));
  const c = el("div", "ic");
  c.append(ico(icon, 26));
  b.append(c, el("span", "l", label));
  b.onclick = fn;
  return b;
}

function card(s) {
  const b = el("button", "card");
  const d = el("div");
  d.append(el("b", "", s.n), el("small", "", s.u.replace("https://", "")));
  b.append(fav(s.u, 28), d);
  b.onclick = () => openTarget(s.u);
  return b;
}

/* ---------- splash texts ---------- */
const SPLASHES = [
  "Also try Cherri", "Got milk?", "Don't cry over spilled milk", "Udderly unblocked",
  "Best before never", "Fresh from the fridge", "Now with 100% more milk", "Proxy not included",
  "Cereal not included", "Skim the web", "Lactose tolerant", "Now 2% funnier",
  "Shaken, not stirred", "Moo.", "Cool as a cow", "Straight from the carton"
];
const SPLASH = SPLASHES[Math.floor(Math.random() * SPLASHES.length)]; // picked once per page load

function renderHome(v) {
  const hero = el("section", "hero");
  const logo = el("div", "logo");
  logo.append(ico("drop", 32));
  const splash = el("p", "", SPLASH);
  hero.append(logo, el("h1", "", "Milky"), splash);

  const s = el("input", "search");
  s.placeholder = "Search or enter a URL";
  s.autocomplete = "off";
  s.onkeydown = (e) => { if (e.key === "Enter") submit(s.value); };
  hero.append(s);

  const row = el("div", "tiles");
  ["g", "ai", "m", "music", "c", "w", "apps"].forEach((k) => row.append(tile(pages[k].icon, pages[k].title, () => go(k, true))));
  hero.append(row);

  const bm = el("div", "tiles");
  bookmarks.forEach((b, i) => {
    const t = tile("bookmark", b.name, () => openTarget(b.url));
    t.title = "Right-click to remove";
    t.oncontextmenu = (e) => { e.preventDefault(); if (confirm("Remove bookmark " + b.name + "?")) { bookmarks.splice(i, 1); saveBm(); render(); } };
    bm.append(t);
  });
  bm.append(tile("plus", "Add bookmark", () => {
    const url = prompt("Bookmark URL:");
    if (!url || !url.trim()) return;
    const name = prompt("Name:", url.replace(/^https?:\/\//i, "").split("/")[0]) || url;
    bookmarks.push({ name: name.trim(), url: toUrl(url) });
    saveBm();
    render();
  }, "add"));
  hero.append(bm);

  v.append(hero);
  setTimeout(() => s.focus(), 0);
}


const GAMES_FILES = ["games.json"];               // add more files here, e.g. "games-more.json"
let gamesPromise = null;

function loadGames() {
  if (gamesPromise) return gamesPromise;
  gamesPromise = Promise.allSettled(GAMES_FILES.map((f) =>
    fetch(BASE + f).then((r) => { if (!r.ok) throw new Error(f + ": HTTP " + r.status); return r.json(); })
  )).then((results) => {
    const seen = new Set(), list = [], failed = [];
    results.forEach((r, i) => {
      if (r.status !== "fulfilled") { failed.push(GAMES_FILES[i]); return; }
      const arr = Array.isArray(r.value) ? r.value : (r.value && r.value.games) || [];
      arr.forEach((g) => {
        if (!g || !g.n || !g.u) return;
        let u; try { u = new URL(g.u).href; } catch (e) { return; }
        if (seen.has(u)) return;
        seen.add(u);
        list.push({ n: String(g.n), u, src: String(g.src || "Other"), img: g.img ? String(g.img) : "", direct: !!g.direct });
      });
    });
    if (!list.length) pages.g.sites.forEach((g) => list.push({ n: g.n, u: g.u, src: "Built-in", img: "", direct: false }));
    return { list, failed };
  });
  return gamesPromise;
}

function renderGames(box) {
  const bar = el("div", "bar");
  const q = el("input", "gin");
  q.placeholder = "Search games";
  q.autocomplete = "off";
  const sel = el("select", "gsel");
  const rnd = el("button", "rnd");
  rnd.append(ico("shuffle", 18), el("span", "", "Random"));
  bar.append(q, sel, rnd);

  const count = el("p", "sub", "Loading games…");
  const grid = el("div", "grid games");
  const more = el("button", "more", "Show more");
  box.append(bar, count, grid, more);

  let all = [], list = [], shown = 0;
  const CHUNK = 120;

  function tileFor(g) {
    const b = el("button", "gt");
    if (g.img) {
      const im = mk("img");
      im.className = "cover"; im.alt = ""; im.loading = "lazy"; im.referrerPolicy = "no-referrer"; im.src = g.img;
      im.onerror = () => im.replaceWith(fav(g.u, 40));
      b.append(im);
    } else b.append(fav(g.u, 40));
    b.append(el("div", "nm", g.n));
    b.onclick = () => openSite(g.u, true, g.direct);
    return b;
  }
  function drawMore() {
    const next = list.slice(shown, shown + CHUNK);
    next.forEach((g) => grid.append(tileFor(g)));
    shown += next.length;
    more.style.display = shown < list.length ? "block" : "none";
  }
  function draw() {
    const t = q.value.trim().toLowerCase();
    list = all.filter((g) => (!sel.value || g.src === sel.value) && g.n.toLowerCase().includes(t));
    grid.innerHTML = "";
    shown = 0;
    const sc = $("#scroller");
    if (sc) sc.scrollTop = 0;
    count.textContent = list.length + (list.length === 1 ? " game" : " games");
    if (!list.length) { grid.className = "grid"; grid.append(el("div", "empty", "No games found.")); more.style.display = "none"; return; }
    grid.className = "grid games";
    drawMore();
  }

  q.oninput = draw;
  sel.onchange = draw;
  more.onclick = drawMore;
  rnd.onclick = () => { if (list.length) { const g = list[Math.floor(Math.random() * list.length)]; openSite(g.u, true, g.direct); } };
  try { new IntersectionObserver((e) => { if (e[0].isIntersecting && shown < list.length) drawMore(); }, { rootMargin: "400px" }).observe(more); } catch (e) {}

  loadGames().then(({ list: l, failed }) => {
    all = l;
    const counts = {};
    l.forEach((g) => { counts[g.src] = (counts[g.src] || 0) + 1; });
    const o0 = el("option", "", "All sources (" + l.length + ")"); o0.value = ""; sel.append(o0);
    Object.keys(counts).sort((a, b) => counts[b] - counts[a] || a.localeCompare(b)).forEach((n) => {
      const o = el("option", "", n + " (" + counts[n] + ")"); o.value = n; sel.append(o);
    });
    draw();
    if (failed.length) toast("Couldn't load " + failed.join(", "), true);
  });
}

function renderPage(v, route) {
  const p = pages[route];
  const box = el("section", "page");
  if (!p) {
    box.append(el("h2", "", "Page not found"), el("p", "sub", "milky://" + route + " doesn't exist. Try milky://g, ai, m, music, c, w or apps."));
    v.append(box);
    return;
  }
  const h = el("h2");
  h.append(ico(p.icon, 28), el("span", "", p.title));
  box.append(h);
  if (route === "g") renderGames(box);
  else if (p.all) {
    box.append(el("p", "sub", "Every app in one place"));
    Object.keys(pages).filter((k) => pages[k].sites).forEach((k) => {
      box.append(el("div", "sect", pages[k].title));
      const g = el("div", "grid");
      pages[k].sites.forEach((s) => g.append(card(s)));
      box.append(g);
    });
  } else {
    box.append(el("p", "sub", p.sites.length + " sites"));
    const g = el("div", "grid");
    p.sites.forEach((s) => g.append(card(s)));
    box.append(g);
  }
  v.append(box);
}

function render() {
  renderTabs();
  const cur = tabs.find((t) => t.id === active);
  const route = cur.route;
  root.classList.toggle("site", route === "site");
  ["back", "forward", "reload"].forEach((k) => { $("#nb-" + k).disabled = route !== "site"; });
  tabs.forEach((t) => { if (t.frame) t.frame.classList.toggle("on", t.id === active); });
  $("#addr").value = route === "site" ? cur.url : "milky://" + route;
  const v = $("#view");
  v.innerHTML = "";
  if (route === "site") return;
  if (route === "home") renderHome(v);
  else renderPage(v, route);
}

$("#addr").addEventListener("keydown", (e) => { if (e.key === "Enter") submit(e.target.value); });
$("#addr").addEventListener("focus", (e) => e.target.select());

render();
setTimeout(() => getController().catch(() => {}), 300);
